<?php use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Użytkownicy';?>
<div class="page-head"><div><p class="eyebrow">Administracja</p><h1>Użytkownicy</h1><p class="muted"><?=Html::e($total)?> kont</p></div><div class="actions"><a class="button secondary" href="<?=Html::e(Url::to('/admin/groups'))?>">Grupy</a><a class="button" href="<?=Html::e(Url::to('/admin/users/create'))?>">Dodaj użytkownika</a></div></div>
<section class="card section-card"><form method="get" class="search-admin"><input name="q" value="<?=Html::e($query)?>" placeholder="Szukaj po loginie, imieniu lub e-mailu"><button class="button secondary">Szukaj</button></form><?php if(!$usersList):?><div class="empty-state"><p>Brak użytkowników spełniających kryteria.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>Login</th><th>Imię i nazwisko</th><th>E-mail</th><th>Status</th><th>Ostatnie logowanie</th><th></th></tr></thead><tbody><?php foreach($usersList as $u):?><tr><td><?=Html::e($u['username'])?></td><td><?=Html::e(trim($u['first_name'].' '.$u['last_name']))?></td><td><?=Html::e($u['email'])?></td><td><span class="badge neutral"><?=Html::e($u['status'])?></span></td><td><?=Html::e($u['last_login_at']??'—')?></td><td><a href="<?=Html::e(Url::to('/admin/users/'.$u['id'].'/edit'))?>">Edytuj</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><nav class="pager" aria-label="Paginacja"><?php if($page>1):?><a href="<?=Html::e(Url::to('/admin/users?'.http_build_query(['q'=>$query,'page'=>$page-1])))?>">← Poprzednia</a><?php endif;?><span>Strona <?=Html::e($page)?> z <?=Html::e($pages)?></span><?php if($page<$pages):?><a href="<?=Html::e(Url::to('/admin/users?'.http_build_query(['q'=>$query,'page'=>$page+1])))?>">Następna →</a><?php endif;?></nav></section>
